/** True when the string looks like an email address. */
export function looksLikeEmail(value?: string | null): boolean {
  const t = String(value || '').trim()
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)
}

/**
 * Pick the first non-empty candidate that is not an email.
 * Used for PDF "Generated by" and similar person labels.
 */
export function resolvePersonDisplayName(
  ...candidates: Array<string | null | undefined>
): string {
  for (const candidate of candidates) {
    const t = String(candidate || '').trim()
    if (t && !looksLikeEmail(t)) return t
  }
  return 'Staff'
}

/** Resolve a staff display name from auth + optional users directory row. */
export function resolveStaffName(opts: {
  directoryUser?: { name?: string; displayName?: string; email?: string } | null
  authDisplayName?: string | null
  storedName?: string | null
}): string {
  return resolvePersonDisplayName(
    opts.directoryUser?.name,
    opts.directoryUser?.displayName,
    opts.storedName,
    opts.authDisplayName,
  )
}
